import math

def is_square(k):
    if k < 0:
        return False
    if k == 0:
        return True
    root = int(math.isqrt(k))
    return root * root == k

def is_cool(n):
    if n == 0:
        return False

    # Check the necessary condition: S_n must not be a square.
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return False

    # Backtracking search

    # used[i] is True if number i+1 has been used. Indices 0 to n-1 correspond to numbers 1 to n.
    used = [False] * n

    def search(current_sum, count):
        """
        Attempts to complete the permutation starting from the current state.
        current_sum: the sum of the first 'count' elements.
        count: the length of the permutation built so far.
        """
        if count == n:
            # Successfully built a permutation of length n
            return True

        # Try appending every unused number x
        for x_idx in range(n):
            x = x_idx + 1 # The actual number

            if not used[x_idx]:
                new_sum = current_sum + x

                # Constraint check: new_sum must NOT be a perfect square
                if not is_square(new_sum):
                    used[x_idx] = True

                    if search(new_sum, count + 1):
                        return True # Found a valid continuation

                    # Backtrack
                    used[x_idx] = False

        return False # No valid choice leads to a complete permutation

    # Start the search: initial sum is 0, count is 0.
    return search(0, 0)

